	/** „fas fa-person-hiking” → SVG; '' ako ikonice nema na popisu (ili nije solid). */
	public static function svg( string $classes ): string {
		$list = preg_split( '/\s+/', strtolower( trim( $classes ) ) );
		if ( array_intersect( $list, array( 'far', 'fab', 'fa-regular', 'fa-brands' ) ) ) {
			return '';
		}
		foreach ( $list as $class ) {
			$name = 0 === strpos( $class, 'fa-' ) ? substr( $class, 3 ) : '';
			if ( isset( self::ICONS[ $name ] ) ) {
				list( $w, $d ) = self::ICONS[ $name ];
				return '<svg class="paiz-fa" viewBox="0 0 ' . (int) $w . ' 512" width="' . round( $w / 512, 3 ) . 'em" height="1em" fill="currentColor" aria-hidden="true" focusable="false"><path d="' . esc_attr( $d ) . '"/></svg>';
			}
		}
		return '';
	}
